async function api<T>(path:string,body?:unknown):Promise<T>{
 const attempts=body===undefined?3:1;
 for(let attempt=0;attempt<attempts;attempt++){
  const controller=new AbortController(),timer=window.setTimeout(()=>controller.abort(),10000);
  try{const response=await fetch('/api/'+path,{signal:controller.signal,...(body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)})});if(!response.ok){let error;try{error=await response.json()}catch{error={detail:'La réponse du moteur local est incomplète.'}}throw new Error(formatApiError(error.detail))}return await response.json()}
  catch(e){const transient=e instanceof TypeError||(e as Error).name==='AbortError';if(transient&&attempt+1<attempts){await new Promise(resolve=>window.setTimeout(resolve,400*(attempt+1)));continue}if(transient)throw new Error('Connexion au moteur local interrompue. Réessayez dans un instant.');throw e}finally{window.clearTimeout(timer)}
 }
 throw new Error('Le moteur local est indisponible.');
}

