 const canvasRef=useRef<HTMLDivElement>(null);const [size,setSize]=useState({width:0,height:0});
 useEffect(()=>{const parent=canvasRef.current?.parentElement;if(!parent||!fit)return;const update=()=>{const scale=Math.min(parent.clientWidth/width,parent.clientHeight/height);setSize({width:width*scale,height:height*scale})};update();const observer=new ResizeObserver(update);observer.observe(parent);return()=>observer.disconnect()},[width,height,fit]);
 const [draft,setDraft]=useState<number[]|null>(null);const start=useRef<number[]|null>(null);
